public class SimpleSearchProvider : INotionSearchProvider
{
    private readonly INotionDataProvider _data;

    public SimpleSearchProvider(INotionDataProvider data) => _data = data;

    public async Task<IEnumerable<INotionPage>> SearchPagesAsync(
        string query, NotionSearchFilter? filter)
    {
        var all = await _data.GetChildPagesAsync(null);
        return all.Where(p => p.Title.Contains(query, StringComparison.OrdinalIgnoreCase));
    }

    public Task<IEnumerable<NotionSearchResult>> SearchBlocksAsync(
        string query, NotionSearchFilter? filter)
        => Task.FromResult(Enumerable.Empty<NotionSearchResult>());

    public async Task<(IEnumerable<INotionPage>, IEnumerable<NotionSearchResult>)> SearchAllAsync(
        string query, NotionSearchFilter? filter, int maxResults)
    {
        var pages = await SearchPagesAsync(query, filter);
        return (pages.Take(maxResults), []);
    }
}
